/* HEXA BATTLEGROUNDS setup — PART 7 OF 19. Run parts in order. Safe to re-run. */ create or replace function _host_exec(p_ev uuid, p_arena uuid, p_cmd text, p_args jsonb, p_reason text) returns jsonb language plpgsql as $$ declare a arenas; t teams; r record; v_n int := 0; v_delta interval; v_tpl text; v_round uuid; v_kind text; v_seed int; v_secs int; v_max int; v_teams uuid[]; i int; v_idx int; v_res jsonb; v_role text; p players; v_other uuid; begin if p_arena is not null then select * into a from arenas where id = p_arena for update; end if; select mission_seed into v_seed from events where id = p_ev; case p_cmd when 'open_boarding', 'assign_buses' then if a.phase not in ('lobby', 'boarding') then raise exception 'WRONG_PHASE'; end if; for r in select id, row_number() over (order by number) as rn from teams where arena_id = a.id and ready loop update teams set bus = 1 + ((r.rn - 1) / _cfg(p_ev, 'bus_size'))::int where id = r.id; v_n := v_n + 1; end loop; update arenas set phase = 'boarding' where id = a.id; perform _feed(a.id, 'shuttle.assigned', jsonb_build_object('squads', v_n)); return jsonb_build_object('boarded', v_n); when 'drive' then if a.phase <> 'boarding' then raise exception 'WRONG_PHASE'; end if; update arenas set phase = 'shuttle', shuttle_departed_at = now(), shuttle_arrive_at = now() + _secs(_cfg(p_ev, 'shuttle_seconds')) where id = a.id; perform _feed(a.id, 'shuttle.departed', '{}'::jsonb); when 'finalize_roles' then if a.phase = 'shuttle' then update arenas set shuttle_arrive_at = now() where id = a.id; perform _tick(a.id, true); end if; update arenas set roles_deadline = now() where id = a.id and phase = 'roles'; perform _tick(a.id, true); when 'set_role' then select * into p from players where id = (p_args ->> 'player_id')::uuid; select * into t from teams where id = p.team_id and event_id = p_ev; if t.id is null then raise exception 'NOT_FOUND'; end if; v_role := p_args ->> 'role'; if v_role not in ('captain', 'scout', 'decoder', 'intel') then raise exception 'BAD_ROLE'; end if; select id into v_other from players where team_id = t.id and active and role = v_role and id <> p.id; update players set role = null where id = v_other; update players set role = v_role where id = p.id; if v_other is not null then update players set role = p.role where id = v_other; end if; perform _ping_team(t.id, 'roles'); when 'remove_player' then select * into p from players where id = (p_args ->> 'player_id')::uuid; select * into t from teams where id = p.team_id and event_id = p_ev for update; if t.id is null then raise exception 'NOT_FOUND'; end if; update players set active = false, role = null, session_hash = 'revoked-' || id::text where id = p.id; update teams set roster_locked = false where id = t.id; if (select phase from arenas where id = t.arena_id) in ('lobby', 'boarding') then update teams set ready = false where id = t.id; end if; perform _ping_team(t.id, 'roster'); when 'reopen_team' then update teams set roster_locked = false where id = (p_args ->> 'team_id')::uuid and event_id = p_ev; when 'lock_team' then update teams set roster_locked = true, ready = (select count(*) = 4 from players where team_id = teams.id and active) where id = (p_args ->> 'team_id')::uuid and event_id = p_ev; when 'fill_roles' then perform _finalize_roles((select arena_id from teams where id = (p_args ->> 'team_id')::uuid and event_id = p_ev)); when 'pause' then if a.paused then return '{}'::jsonb; end if; update arenas set paused = true, paused_at = now() where id = a.id; perform _feed(a.id, 'game.paused', '{}'::jsonb); when 'resume' then if not a.paused then return '{}'::jsonb; end if; v_delta := now() - a.paused_at; update arenas set paused = false, paused_at = null, shuttle_arrive_at = shuttle_arrive_at + v_delta, roles_deadline = roles_deadline + v_delta, play_started_at = play_started_at + v_delta, zone_next_at = zone_next_at + v_delta, last_airdrop_at = last_airdrop_at + v_delta where id = a.id; update mission_instances set deadline = deadline + v_delta, fallback_at = fallback_at + v_delta, started_at = started_at + v_delta where arena_id = a.id and status = 'active'; update battles set deadline = deadline + v_delta where arena_id = a.id and status = 'active'; update sync_rounds set deadline = deadline + v_delta, started_at = started_at + v_delta where arena_id = a.id and status = 'active'; update airdrops set expires_at = expires_at + v_delta where arena_id = a.id and status = 'open'; update teams set travel_arrive_at = travel_arrive_at + v_delta, recovery_deadline = recovery_deadline + v_delta, attack_cooldown_until = attack_cooldown_until + v_delta, protected_until = protected_until + v_delta, jammed_until = jammed_until + v_delta, scan_until = scan_until + v_delta where arena_id = a.id; perform _feed(a.id, 'game.resumed', '{}'::jsonb); when 'broadcast' then update arenas set overlay = overlay || jsonb_build_object('broadcast', jsonb_build_object( 'text', left(p_args ->> 'text', 280), 'tone', coalesce(p_args ->> 'tone', 'info'), 'at', now())) where id = a.id; perform _feed(a.id, 'story.broadcast', jsonb_build_object('text', left(p_args ->> 'text', 280))); when 'clear_overlay' then update arenas set overlay = '{}'::jsonb where id = a.id; when 'blackout' then update arenas set overlay = overlay || jsonb_build_object('blackout', coalesce((p_args ->> 'on')::boolean, true)) where id = a.id; when 'countdown' then update arenas set overlay = overlay || jsonb_build_object('countdown', jsonb_build_object( 'until', now() + _secs(coalesce((p_args ->> 'seconds')::int, 10)), 'label', coalesce(p_args ->> 'label', ''))) where id = a.id; when 'story' then insert into story_events(arena_id, kind, title, body) values (a.id, 'transmission', coalesce(p_args ->> 'title', 'Squad 00 transmission'), coalesce(p_args ->> 'body', '')); perform _feed(a.id, 'squad00.transmission', jsonb_build_object('title', p_args ->> 'title')); when 'bargain' then insert into story_events(arena_id, kind, title, body, offer, expires_at) values (a.id, 'bargain', coalesce(p_args ->> 'title', 'Squad 00 offers a deal'), coalesce(p_args ->> 'body', ''), jsonb_build_object('coins', coalesce((p_args ->> 'coins')::int, 60), 'threat', coalesce((p_args ->> 'threat')::int, 1), 'trust', coalesce((p_args ->> 'trust')::int, -5)), now() + make_interval(mins => coalesce((p_args ->> 'minutes')::int, 3))); perform _feed(a.id, 'squad00.bargain', '{}'::jsonb); when 'zone_warn' then if a.zone_stage >= 5 then raise exception 'ZONE_FINAL'; end if; update arenas set zone_next_at = now() + _secs(coalesce((p_args ->> 'seconds')::int, _cfg(p_ev, 'zone_warning'))) where id = a.id; perform _feed(a.id, 'zone.warning', jsonb_build_object('stage', a.zone_stage + 1)); when 'zone_now' then if a.zone_stage >= 5 then raise exception 'ZONE_FINAL'; end if; perform _zone_advance(a.id); when 'zone_cancel' then update arenas set zone_next_at = null where id = a.id; perform _feed(a.id, 'zone.cancelled', '{}'::jsonb); when 'zone_set' then update arenas set zone_stage = greatest(0, least(5, (p_args ->> 'stage')::int)), zone_next_at = null where id = a.id; perform _apply_zone(a.id); perform _feed(a.id, 'zone.collapsed', jsonb_build_object('stage', (p_args ->> 'stage')::int)); when 'set_location' then if p_args ->> 'location' in ('tr14', 'gate_1', 'hx_lobby') and not coalesce((p_args ->> 'enabled')::boolean, true) then raise exception 'LOCATION_REQUIRED'; end if; update locations set enabled = coalesce((p_args ->> 'enabled')::boolean, true) where id = p_args ->> 'location'; when 'spawn_airdrop' then return jsonb_build_object('airdrop', _spawn_airdrop(a.id, nullif(p_args ->> 'location', ''), coalesce(p_args ->> 'tier', 'common'))); when 'relocate' then select * into t from teams where id = (p_args ->> 'team_id')::uuid and event_id = p_ev for update; if t.id is null or not exists (select 1 from locations where id = p_args ->> 'location') then raise exception 'NOT_FOUND'; end if; update teams set location_id = p_args ->> 'location', state = case when state = 'traveling' then 'idle' else state end, travel_to = null, travel_from = null, travel_arrive_at = null, dropped = true, visit_missions = 0 where id = t.id; perform _ping_team(t.id, 'move'); when 'adjust' then if p_reason is null or length(trim(p_reason)) < 3 then raise exception 'REASON_REQUIRED'; end if; select * into t from teams where id = (p_args ->> 'team_id')::uuid and event_id = p_ev; if t.id is null then raise exception 'NOT_FOUND'; end if; perform _apply(t.id, 'host_adjust', coalesce((p_args ->> 'points')::int, 0), coalesce((p_args ->> 'coins')::int, 0), coalesce((p_args ->> 'hp')::int, 0), coalesce((p_args ->> 'trust')::int, 0), null, p_reason, 'host'); if coalesce((p_args ->> 'final_points')::int, 0) <> 0 then update teams set final_points = final_points + (p_args ->> 'final_points')::int where id = t.id; end if; if (p_args ->> 'item') is not null then perform _add_item(t.id, p_args ->> 'item', coalesce((p_args ->> 'qty')::int, 1)); end if; select * into t from teams where id = t.id; if t.hp <= 0 then perform _enter_recovery(t.id); end if; perform _ping_team(t.id, 'score'); when 'respawn' then perform _respawn((p_args ->> 'team_id')::uuid, 'host'); when 'reveal_hint' then update mission_instances set hint_used = true where id = (p_args ->> 'instance_id')::uuid; perform _ping_team((select team_id from mission_instances where id = (p_args ->> 'instance_id')::uuid), 'hint'); when 'cancel_instance' then update mission_instances mi set status = 'cancelled' from teams t2 where mi.id = (p_args ->> 'instance_id')::uuid and mi.team_id = t2.id and t2.event_id = p_ev and mi.status = 'active' and mi.kind <> 'battle'; perform _ping_team((select team_id from mission_instances where id = (p_args ->> 'instance_id')::uuid), 'mission'); when 'assign_mission' then select * into t from teams where id = (p_args ->> 'team_id')::uuid and event_id = p_ev; if t.id is null then raise exception 'NOT_FOUND'; end if; if not exists (select 1 from mission_templates where id = p_args ->> 'template_id' and status in ('approved', 'published')) then raise exception 'TEMPLATE_NOT_APPROVED'; end if; update mission_instances set status = 'cancelled' where team_id = t.id and status = 'active' and kind <> 'battle'; return jsonb_build_object('instance', _start_instance(t.id, p_args ->> 'template_id')); when 'end_battle' then perform _resolve_battle((p_args ->> 'battle_id')::uuid, nullif(p_args ->> 'winner_id', '')::uuid); when 'hide_message' then update chat_messages c set hidden = true from arenas ar where c.id = (p_args ->> 'message_id')::bigint and ar.id = c.arena_id and ar.event_id = p_ev; when 'begin_finale' then if a.phase <> 'play' then raise exception 'WRONG_PHASE'; end if; for r in select id from battles where arena_id = a.id and status = 'active' loop perform _resolve_battle(r.id, null); end loop; update mission_instances set status = 'cancelled' where arena_id = a.id and status = 'active'; update teams set state = 'idle', recovery_deadline = null, hp = greatest(hp, _cfg(p_ev, 'hp_respawn')) where arena_id = a.id and state = 'recovery'; update teams set location_id = 'tr14', state = 'idle', travel_to = null, travel_from = null, travel_arrive_at = null where arena_id = a.id and ready; update airdrops set status = 'expired' where arena_id = a.id and status = 'open'; update arenas set phase = 'finale', zone_stage = 5, zone_next_at = null, finale_stage = 'A' where id = a.id; perform _feed(a.id, 'final.started', '{}'::jsonb); when 'finale_stage' then if a.phase <> 'finale' then raise exception 'WRONG_PHASE'; end if; if p_args ->> 'stage' not in ('A', 'B', 'C', 'D', 'E', 'F') then raise exception 'BAD_STAGE'; end if; update arenas set finale_stage = p_args ->> 'stage' where id = a.id; perform _feed(a.id, 'final.stage', jsonb_build_object('stage', p_args ->> 'stage')); when 'reveal_squad00' then update arenas set finale_stage = 'D' where id = a.id and phase = 'finale'; insert into story_events(arena_id, kind, title, body) values (a.id, 'reveal', 'The truth about Squad 00', 'See the main screen.'); perform _feed(a.id, 'squad00.revealed', '{}'::jsonb); when 'launch_sync' then if a.phase <> 'finale' then raise exception 'WRONG_PHASE'; end if; v_kind := coalesce(p_args ->> 'kind', 'finale_battle'); if v_kind not in ('finale_entry', 'finale_exchange', 'finale_battle', 'final_code') then raise exception 'BAD_KIND'; end if; select count(*) into v_idx from sync_rounds where arena_id = a.id and kind = v_kind; v_tpl := p_args ->> 'template_id'; if v_tpl is null then select id into v_tpl from mission_templates where kind = v_kind and status = 'published' order by md5(v_seed::text || id) offset (v_idx % greatest(1, (select count(*) from mission_templates where kind = v_kind and status = 'published'))::int) limit 1; end if; if v_tpl is null then raise exception 'NO_TEMPLATE'; end if; v_secs := coalesce((p_args ->> 'seconds')::int, nullif(_cfg(p_ev, 'sync_seconds'), 0), (select time_limit from mission_templates where id = v_tpl)); v_max := case v_kind when 'finale_entry' then _cfg(p_ev, 'finale_entry_max') when 'finale_exchange' then _cfg(p_ev, 'finale_exchange_max') else _cfg(p_ev, 'finale_max') end; update sync_rounds set status = 'closed' where arena_id = a.id and status = 'active'; update mission_instances set status = 'cancelled' where arena_id = a.id and status = 'active'; insert into sync_rounds(arena_id, stage, kind, template_id, deadline, max_points) values (a.id, coalesce(a.finale_stage, 'C'), v_kind, v_tpl, now() + _secs(v_secs), v_max) returning id into v_round; update arenas set sync_round_id = v_round where id = a.id; select array_agg(id order by number) into v_teams from teams where arena_id = a.id and ready; for i in 1..coalesce(array_length(v_teams, 1), 0) loop perform _start_instance(v_teams[i], v_tpl, 'tr14', null, null, v_round, now() + _secs(v_secs), case when array_length(v_teams, 1) > 1 then v_teams[1 + (i % array_length(v_teams, 1))] end); end loop; perform _feed(a.id, 'sync.started', jsonb_build_object('kind', v_kind, 'seconds', v_secs)); return jsonb_build_object('round', v_round, 'template', v_tpl); when 'close_sync' then update sync_rounds set deadline = now() where arena_id = a.id and status = 'active'; update mission_instances set deadline = now() where arena_id = a.id and status = 'active' and sync_round_id is not null; perform _tick(a.id, true); when 'lock_results' then update sync_rounds set deadline = now() where arena_id = a.id and status = 'active'; perform _tick(a.id, true); v_res := _standings(a.id); update arenas set results = v_res, results_locked = true, phase = 'results', finale_stage = 'F' where id = a.id; perform _feed(a.id, 'results.locked', '{}'::jsonb); return jsonb_build_object('standings', v_res); when 'unlock_results' then update arenas set results_locked = false, winner_revealed = false, phase = 'finale' where id = a.id; when 'reveal_winner' then if not a.results_locked then raise exception 'LOCK_RESULTS_FIRST'; end if; update arenas set winner_revealed = true where id = a.id; perform _feed(a.id, 'winner.revealed', jsonb_build_object('team', a.results -> 0 -> 'number')); when 'reveal_grand' then if exists (select 1 from arenas where event_id = p_ev and not results_locked) then raise exception 'LOCK_ALL_MAPS_FIRST'; end if; update events set grand_revealed = true where id = p_ev; for r in select id from arenas where event_id = p_ev loop perform _ping_arena(r.id, 'grand'); end loop; when 'end_game' then update arenas set phase = 'ended' where id = a.id; when 'revoke_spectator' then update arenas set spectator_token = replace(gen_random_uuid()::text, '-', '') where id = a.id; perform _ping_arena(a.id, 'revoked'); when 'reset_arena' then if coalesce(p_args ->> 'confirm', '') <> 'RESET' then raise exception 'CONFIRM_REQUIRED'; end if; delete from submissions s using mission_instances mi where s.instance_id = mi.id and mi.arena_id = a.id; delete from mission_instances where arena_id = a.id; delete from battles where arena_id = a.id; delete from airdrops where arena_id = a.id; delete from sync_rounds where arena_id = a.id; delete from chat_messages where arena_id = a.id; delete from alliances where arena_id = a.id; delete from story_events where arena_id = a.id; delete from game_feed where arena_id = a.id; delete from ledger where arena_id = a.id; delete from inventory where team_id in (select id from teams where arena_id = a.id); update teams set hp = 100, shield = 0, coins = 50, points = 0, trust = 0, final_points = 0, missions_completed = 0, battle_wins = 0, location_id = null, dropped = false, state = 'idle', travel_from = null, travel_to = null, travel_arrive_at = null, recovery_deadline = null, attack_cooldown_until = null, protected_until = null, jammed_until = null, scan_until = null, beacon = false, zone_penalty_stage = 0, mission_counter = 0, visit_missions = 0, bargains = '[]'::jsonb, bus = null where arena_id = a.id; for r in select id from teams where arena_id = a.id loop perform _add_item(r.id, 'pistol', 1); perform _add_item(r.id, 'medkit', 1); end loop; update players set role = null where team_id in (select id from teams where arena_id = a.id); update arenas set phase = 'lobby', paused = false, paused_at = null, shuttle_departed_at = null, shuttle_arrive_at = null, roles_deadline = null, play_started_at = null, zone_stage = 0, zone_next_at = null, finale_stage = null, sync_round_id = null, threat = 0, last_airdrop_at = null, results_locked = false, results = null, winner_revealed = false, overlay = '{}'::jsonb where id = a.id; update events set grand_revealed = false where id = p_ev; else raise exception 'UNKNOWN_COMMAND'; end case; return '{}'::jsonb; end $$;
